import { Cart } from './cart'
import { features } from '../config/features'

const FLAT_RATE = 4.95

export function qualifiesForFreeShipping(cart: Cart): boolean {
  return features.freeShipping && cart.subtotal >= features.freeShippingThreshold
}

export function shippingFor(cart: Cart): number {
  if (cart.items.length === 0) return 0
  if (qualifiesForFreeShipping(cart)) return 0
  return FLAT_RATE
}

