changes.test/checkout.test.ts:
import { describe, expect, it } from 'vitest'
import { shippingFor } from '../src/checkout'

const cart = (subtotal: number, items = 1) => ({ subtotal, items: Array(items).fill({}) })

describe('shippingFor', () => {
  it('charges the flat rate under the threshold', () => {
    expect(shippingFor(cart(49.99))).toBe(4.95)
  })

  it('is free at the threshold', () => {
    expect(shippingFor(cart(50))).toBe(0)
  })

  it('never charges an empty cart', () => {
    expect(shippingFor(cart(0, 0))).toBe(0)
  })
})

